CREATE TABLE environments (id VARCHAR(36) PRIMARY KEY, name VARCHAR(120) NOT NULL UNIQUE, mode VARCHAR(20) NOT NULL CHECK (mode IN ('lab','production')), cidr VARCHAR(80) NOT NULL);
CREATE TABLE assets (environment_id VARCHAR(36) NOT NULL REFERENCES environments(id), ip VARCHAR(80) NOT NULL, first_seen DOUBLE PRECISION NOT NULL, last_seen DOUBLE PRECISION NOT NULL, PRIMARY KEY(environment_id,ip));
CREATE TABLE observations (id VARCHAR(64) PRIMARY KEY, environment_id VARCHAR(36) NOT NULL REFERENCES environments(id), ts DOUBLE PRECISION NOT NULL, src VARCHAR(80) NOT NULL, dst VARCHAR(80) NOT NULL, port INTEGER NOT NULL, service VARCHAR(120) NOT NULL, external INTEGER NOT NULL);
CREATE TABLE plans (id VARCHAR(36) PRIMARY KEY, environment_id VARCHAR(36) NOT NULL REFERENCES environments(id), tool VARCHAR(120) NOT NULL, action VARCHAR(20) NOT NULL, target VARCHAR(80) NOT NULL, state VARCHAR(40) NOT NULL, created_at VARCHAR(40) NOT NULL);
CREATE TABLE audit (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, actor VARCHAR(240) NOT NULL, action VARCHAR(80) NOT NULL, resource VARCHAR(120) NOT NULL, result VARCHAR(120) NOT NULL, timestamp VARCHAR(40) NOT NULL);
CREATE TABLE findings (id VARCHAR(64) PRIMARY KEY, environment_id VARCHAR(36) NOT NULL REFERENCES environments(id), tool VARCHAR(120) NOT NULL, application VARCHAR(120) NOT NULL, title VARCHAR(240) NOT NULL, severity VARCHAR(30) NOT NULL, resource VARCHAR(500) NOT NULL, rule VARCHAR(240) NOT NULL, description VARCHAR(2000) NOT NULL, solution VARCHAR(2000) NOT NULL, imported_at VARCHAR(40) NOT NULL);
CREATE TABLE report_imports (id VARCHAR(36) PRIMARY KEY, environment_id VARCHAR(36) NOT NULL REFERENCES environments(id), tool VARCHAR(120) NOT NULL, application VARCHAR(120) NOT NULL, findings INTEGER NOT NULL, duplicates INTEGER NOT NULL, imported_at VARCHAR(40) NOT NULL);
CREATE INDEX findings_environment ON findings(environment_id);
CREATE INDEX observations_environment ON observations(environment_id);
